import { MapView } from "@/components/Map";
import { Button } from "@/components/ui/button";
import { trpc } from "@/lib/trpc";
import { currency, date, dateTime, inputDateTime, labels, number, readUpload, statusTone } from "@/lib/forest";
import { exportDashboardExcel, exportDashboardPdf } from "@/lib/exporters";
import {
  AlertTriangle,
  ArrowDownRight,
  ArrowUpRight,
  CalendarClock,
  Check,
  ChevronRight,
  ClipboardCheck,
  Download,
  FilePlus2,
  FileText,
  FolderOpen,
  Landmark,
  Loader2,
  MapPin,
  Plus,
  ReceiptText,
  Scale,
  ShieldCheck,
  ScrollText,
  Trees,
  Upload,
  X,
} from "lucide-react";
import { FormEvent, ReactNode, useMemo, useState } from "react";
import { Bar, BarChart, Cell, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { toast } from "sonner";

const forestGreen = "#1f5d42";
const chartPalette = ["#1f5d42", "#8aa66a", "#c3a667", "#5f7e6b", "#d5804e"];

function PageHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: ReactNode }) {
  return <header className="mb-7 flex flex-col gap-4 lg:mb-9 lg:flex-row lg:items-end lg:justify-between"><div><p className="text-[11px] font-bold uppercase tracking-[0.18em] text-[#628670]">{eyebrow}</p><h1 className="mt-2 text-3xl font-semibold tracking-tight text-[#173f2e] sm:text-4xl">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-[#6b7b71]">{description}</p></div>{action}</header>;
}

function Panel({ children, className = "" }: { children: ReactNode; className?: string }) {
  return <section className={`rounded-2xl border border-[#dbe6da] bg-white shadow-[0_18px_45px_-37px_rgba(27,75,54,0.58)] ${className}`}>{children}</section>;
}

function StatusPill({ label, value }: { label: string; value: string }) {
  const tone = statusTone(value);
  const colors = { green: "bg-[#e6f2e9] text-[#246142]", gold: "bg-[#fbf3df] text-[#8a6525]", red: "bg-[#fce9e7] text-[#a43a33]", gray: "bg-[#eff2ef] text-[#66736a]" };
  return <span className={`inline-flex rounded-full px-2.5 py-1 text-[11px] font-semibold ${colors[tone]}`}>{label}</span>;
}

function Modal({ open, onClose, title, children }: { open: boolean; onClose: () => void; title: string; children: ReactNode }) {
  if (!open) return null;
  return <div className="fixed inset-0 z-50 flex items-end justify-center bg-[#10281d]/35 p-0 backdrop-blur-[2px] sm:items-center sm:p-5" role="dialog" aria-modal="true" aria-label={title}><div className="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-t-[1.8rem] bg-[#f7f9f4] shadow-2xl sm:rounded-[1.8rem]"><div className="sticky top-0 z-10 flex items-center justify-between border-b border-[#dfe8dd] bg-[#f7f9f4]/95 px-5 py-4 backdrop-blur"><h2 className="text-lg font-semibold text-[#173f2e]">{title}</h2><button onClick={onClose} className="rounded-xl p-2 text-[#64756a] hover:bg-white" aria-label="Fechar"><X className="h-5 w-5" /></button></div><div className="p-5 sm:p-7">{children}</div></div></div>;
}

function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) {
  return <label className="block"><span className="mb-1.5 block text-xs font-semibold text-[#355745]">{label}</span>{children}{hint && <span className="mt-1 block text-[11px] leading-4 text-[#829087]">{hint}</span>}</label>;
}

const inputClass = "h-10 w-full rounded-xl border border-[#d8e3d7] bg-white px-3 text-sm text-[#183c2b] outline-none transition placeholder:text-[#9aa89f] focus:border-[#4e8a68] focus:ring-4 focus:ring-[#dcefe2]";
const selectClass = inputClass;
const textareaClass = "min-h-24 w-full rounded-xl border border-[#d8e3d7] bg-white px-3 py-2.5 text-sm text-[#183c2b] outline-none transition placeholder:text-[#9aa89f] focus:border-[#4e8a68] focus:ring-4 focus:ring-[#dcefe2]";

function FormActions({ loading, onCancel }: { loading: boolean; onCancel: () => void }) {
  return <div className="mt-7 flex justify-end gap-3 border-t border-[#e3ebe2] pt-5"><Button type="button" variant="outline" onClick={onCancel} disabled={loading} className="border-[#cfdccf] bg-white text-[#31523e]">Cancelar</Button><Button type="submit" disabled={loading} className="bg-[#1f5d42] hover:bg-[#174b35] text-white">{loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}Salvar registro</Button></div>;
}

function LoadingPanel() { return <Panel className="p-12 text-center"><Loader2 className="mx-auto h-6 w-6 animate-spin text-[#1f5d42]" /><p className="mt-3 text-sm text-[#6b7b71]">Carregando informações da operação...</p></Panel>; }
function EmptyPanel({ icon: Icon, title, description, action }: { icon: typeof Trees; title: string; description: string; action?: ReactNode }) { return <Panel className="p-10 text-center"><div className="mx-auto flex h-12 w-12 items-center justify-center rounded-2xl bg-[#eef5ed] text-[#2d704d]"><Icon className="h-5 w-5" /></div><h3 className="mt-4 font-semibold text-[#173f2e]">{title}</h3><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-[#728078]">{description}</p>{action && <div className="mt-5">{action}</div>}</Panel>; }

function MetricCard({ label, value, note, icon: Icon, accent = "green" }: { label: string; value: string; note: string; icon: typeof Trees; accent?: "green" | "gold" | "red" }) {
  const colors = { green: "bg-[#e8f4ea] text-[#287047]", gold: "bg-[#fbf2de] text-[#956d29]", red: "bg-[#fce9e7] text-[#ac4238]" };
  return <Panel className="p-5"><div className="flex items-start justify-between"><div><p className="text-xs font-medium text-[#687a6e]">{label}</p><p className="mt-2 text-2xl font-semibold tracking-tight text-[#173f2e]">{value}</p><p className="mt-1 text-[11px] text-[#87958d]">{note}</p></div><div className={`flex h-10 w-10 items-center justify-center rounded-xl ${colors[accent]}`}><Icon className="h-5 w-5" /></div></div></Panel>;
}

function FilePicker({ onChange, accept = "image/*,application/pdf" }: { onChange: (file?: File) => void; accept?: string }) {
  return <label className="flex cursor-pointer items-center gap-3 rounded-xl border border-dashed border-[#b9ceb9] bg-[#f8fbf7] px-3 py-3 text-sm text-[#557060] hover:border-[#4e8a68]"><Upload className="h-4 w-4 text-[#2f704d]" /><span>Selecionar foto ou arquivo</span><input type="file" accept={accept} className="hidden" onChange={event => onChange(event.target.files?.[0])} /></label>;
}

export function DashboardPage() {
  const [month, setMonth] = useState("");
  const [standId, setStandId] = useState("");
  const months = useMemo(() => Array.from({ length: 12 }, (_, index) => {
    const current = new Date(new Date().getFullYear(), new Date().getMonth() - index, 1);
    const value = `${current.getFullYear()}-${String(current.getMonth() + 1).padStart(2, "0")}`;
    return { value, label: current.toLocaleDateString("pt-BR", { month: "long", year: "numeric" }) };
  }), []);
  const filterInput = useMemo(() => ({ month: month || undefined, standId: standId ? Number(standId) : undefined }), [month, standId]);
  const dashboard = trpc.forest.dashboard.useQuery(filterInput);
  if (dashboard.isLoading) return <LoadingPanel />;
  if (dashboard.error) return <EmptyPanel icon={AlertTriangle} title="Não foi possível carregar o painel" description={dashboard.error.message} />;
  const data = dashboard.data!;
  const hasData = data.totals.properties > 0;
  const filterLabel = `${month ? months.find(item => item.value === month)?.label || month : "todos os meses"} · ${standId ? data.filterOptions.find(item => item.id === Number(standId))?.code || "talhão selecionado" : "todos os talhões"}`;
  return <>
    <PageHeading eyebrow="Central de operação" title="Controle florestal em uma só visão." description="Acompanhe áreas, produção, caixa e riscos operacionais de forma centralizada. Registros aprovados alimentam os indicadores." action={<div className="flex flex-wrap items-center gap-2 rounded-2xl border border-[#dbe6da] bg-white p-2 shadow-[0_12px_34px_-27px_rgba(27,75,54,0.5)]"><select value={month} onChange={event => setMonth(event.target.value)} className="h-9 rounded-lg border-0 bg-[#f4f8f3] px-3 text-xs font-medium text-[#345845] outline-none"><option value="">Todos os meses</option>{months.map(item => <option key={item.value} value={item.value}>{item.label}</option>)}</select><select value={standId} onChange={event => setStandId(event.target.value)} className="h-9 rounded-lg border-0 bg-[#f4f8f3] px-3 text-xs font-medium text-[#345845] outline-none"><option value="">Todos os talhões</option>{data.filterOptions.map(item => <option key={item.id} value={item.id}>{item.code} · {item.propertyName}</option>)}</select>{(month || standId) && <button onClick={() => { setMonth(""); setStandId(""); }} className="px-2 text-xs font-semibold text-[#2e704c] hover:underline">Limpar</button>}</div>} />
    <div className="mb-5 flex flex-wrap justify-end gap-2"><Button size="sm" variant="outline" onClick={() => exportDashboardExcel(data, filterLabel)} className="border-[#c9dbca] bg-white text-[#2b6846]"><Download className="mr-1.5 h-3.5 w-3.5" />Excel do painel</Button><Button size="sm" variant="outline" onClick={() => exportDashboardPdf(data, filterLabel)} className="border-[#c9dbca] bg-white text-[#2b6846]"><FileText className="mr-1.5 h-3.5 w-3.5" />PDF do painel</Button></div>
    {!hasData && <Panel className="mb-7 overflow-hidden !bg-[#173f2e] !text-white"><div className="grid gap-5 p-6 sm:p-8 lg:grid-cols-[1.4fr_0.85fr] lg:items-end"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#bdd9c5]">Configuração inicial</p><h2 className="mt-2 text-2xl font-semibold tracking-tight">Comece pela propriedade e pelos talhões.</h2><p className="mt-3 max-w-xl text-sm leading-6 text-[#c9ded0]">Depois, registre contratos, tickets de balança, despesas e documentos. Assim, os indicadores e alertas serão calculados com os dados reais da sua operação.</p></div><div className="flex items-center gap-3 rounded-2xl border border-white/10 bg-white/5 p-4"><ShieldCheck className="h-9 w-9 shrink-0 text-[#e4c47d]" /><p className="text-sm leading-5 text-[#d7e8db]">A plataforma não usa dados fictícios: seus painéis iniciam vazios e passam a refletir os lançamentos confirmados.</p></div></div></Panel>}
    {(data.dueSoon.length > 0 || data.totals.overdueTickets > 0) && <Panel className="mb-5 overflow-hidden border-[#efcfc9] !bg-[#fff7f5]"><div className="flex flex-col gap-3 p-5 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-start gap-3"><div className="rounded-xl bg-[#fce2dd] p-2 text-[#ad483a]"><AlertTriangle className="h-5 w-5" /></div><div><p className="font-semibold text-[#8c3b31]">Atenção operacional necessária</p><p className="mt-1 text-sm text-[#8b625d]">{data.dueSoon.length ? `${data.dueSoon.length} contrato(s) com prazo de até 30 dias` : "Nenhum prazo contratual crítico"}{data.dueSoon.length && data.totals.overdueTickets ? " e " : ""}{data.totals.overdueTickets ? `${data.totals.overdueTickets} ticket(s) pendente(s) fora do prazo` : ""}.</p></div></div><div className="flex flex-wrap gap-2">{data.dueSoon.slice(0, 2).map(item => <span key={item.contract.id} className="rounded-lg border border-[#edd3ce] bg-white px-2.5 py-1 text-xs font-semibold text-[#9a4438]">{item.contract.code}: {item.days < 0 ? "atrasado" : `${item.days}d`}</span>)}{data.totals.overdueTickets > 0 && <span className="rounded-lg border border-[#edd3ce] bg-white px-2.5 py-1 text-xs font-semibold text-[#9a4438]">Tickets atrasados</span>}</div></div></Panel>}
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Toneladas extraídas" value={`${number(data.totals.tons, 3)} t`} note="Tickets conferidos" icon={Scale} /><MetricCard label="Receita aprovada" value={currency(data.totals.revenue)} note="Lançamentos aprovados" icon={ArrowUpRight} /><MetricCard label="Custo operacional" value={currency(data.totals.cost)} note="Despesas aprovadas" icon={ArrowDownRight} accent="gold" /><MetricCard label="Alertas abertos" value={String(data.totals.openIncidents)} note={`${data.totals.pendingTickets} ticket(s) pendente(s)`} icon={AlertTriangle} accent={data.totals.openIncidents ? "red" : "green"} /></div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.35fr_0.9fr]"><Panel className="p-5 sm:p-6"><div className="mb-5 flex items-center justify-between"><div><h2 className="font-semibold text-[#173f2e]">Produção por talhão</h2><p className="mt-1 text-xs text-[#78867d]">Somatório de tickets em situação conferida.</p></div><span className="rounded-lg bg-[#eef5ed] px-2.5 py-1 text-xs font-semibold text-[#2f704d]">{data.totals.stands} talhão(ões)</span></div>{data.tonsByStand.length ? <div className="h-64"><ResponsiveContainer width="100%" height="100%"><BarChart data={data.tonsByStand} margin={{ top: 10, right: 8, left: -18, bottom: 0 }}><XAxis dataKey="name" tickLine={false} axisLine={false} tick={{ fill: "#64756a", fontSize: 12 }} /><YAxis tickLine={false} axisLine={false} tick={{ fill: "#64756a", fontSize: 11 }} /><Tooltip cursor={{ fill: "#f1f6f0" }} formatter={(value: number) => [`${number(value, 3)} t`, "Toneladas"]} /><Bar dataKey="toneladas" fill={forestGreen} radius={[7, 7, 2, 2]} maxBarSize={48} /></BarChart></ResponsiveContainer></div> : <div className="flex h-64 items-center justify-center rounded-xl bg-[#f8faf6] text-center text-sm text-[#859289]">Os dados de produção aparecerão após a conferência dos tickets.</div>}</Panel>
      <Panel className="p-5 sm:p-6"><div className="mb-4"><h2 className="font-semibold text-[#173f2e]">Despesas por categoria</h2><p className="mt-1 text-xs text-[#78867d]">Somente lançamentos aprovados.</p></div>{data.expenseByCategory.length ? <div className="grid h-64 grid-cols-[1fr_0.9fr] items-center"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={data.expenseByCategory} dataKey="value" nameKey="name" innerRadius={46} outerRadius={76} paddingAngle={4}>{data.expenseByCategory.map((_, index) => <Cell key={index} fill={chartPalette[index % chartPalette.length]} />)}</Pie><Tooltip formatter={(value: number) => currency(value)} /></PieChart></ResponsiveContainer><div className="space-y-2">{data.expenseByCategory.map((item, index) => <div key={item.name} className="flex items-start gap-2 text-xs text-[#5f7066]"><span className="mt-1 h-2 w-2 rounded-full" style={{ background: chartPalette[index % chartPalette.length] }} /><span className="leading-4">{labels.category[item.name as keyof typeof labels.category] || item.name}<strong className="block font-semibold text-[#314b3b]">{currency(item.value)}</strong></span></div>)}</div></div> : <div className="flex h-64 items-center justify-center rounded-xl bg-[#f8faf6] text-center text-sm text-[#859289]">As despesas aprovadas serão distribuídas aqui por categoria.</div>}</Panel></div>
    <div className="mt-5 grid gap-5 xl:grid-cols-2"><Panel className="p-5 sm:p-6"><div className="mb-4 flex items-center justify-between"><div><h2 className="font-semibold text-[#173f2e]">Prazos contratuais</h2><p className="mt-1 text-xs text-[#78867d]">Contratos ativos ou suspensos com vencimento em até 30 dias.</p></div><CalendarClock className="h-5 w-5 text-[#8a9d8e]" /></div>{data.dueSoon.length ? <div className="divide-y divide-[#edf1eb]">{data.dueSoon.map(item => <div key={item.contract.id} className="flex items-center justify-between gap-4 py-3"><div><p className="text-sm font-semibold text-[#274a38]">{item.contract.code} <span className="font-normal text-[#7b897f]">· {item.contract.buyerName}</span></p><p className="mt-1 text-xs text-[#7a897f]">{item.propertyName} {item.standCode ? `· ${item.standCode}` : ""} · Vence em {date(item.contract.deadline)}</p></div><StatusPill label={item.days < 0 ? `${Math.abs(item.days)}d atrasado` : item.days === 0 ? "vence hoje" : `${item.days} dias`} value={item.days < 0 ? "critica" : item.days <= 7 ? "alta" : "media"} /></div>)}</div> : <p className="rounded-xl bg-[#f8faf6] px-4 py-7 text-center text-sm text-[#849187]">Não há prazos críticos registrados.</p>}</Panel>
      <Panel className="p-5 sm:p-6"><div className="mb-4 flex items-center justify-between"><div><h2 className="font-semibold text-[#173f2e]">Riscos e ocorrências</h2><p className="mt-1 text-xs text-[#78867d]">Registros não resolvidos exigem acompanhamento.</p></div><AlertTriangle className="h-5 w-5 text-[#b06e38]" /></div>{data.openIncidents.length ? <div className="divide-y divide-[#edf1eb]">{data.openIncidents.map(item => <div key={item.incident.id} className="flex items-center justify-between gap-4 py-3"><div><p className="text-sm font-semibold text-[#274a38]">{item.incident.title}</p><p className="mt-1 text-xs text-[#7a897f]">{labels.incidentCategory[item.incident.category]} · {item.standCode || item.propertyName} · {date(item.incident.occurredAt)}</p></div><StatusPill label={labels.severity[item.incident.severity]} value={item.incident.severity} /></div>)}</div> : <p className="rounded-xl bg-[#f8faf6] px-4 py-7 text-center text-sm text-[#849187]">Nenhuma ocorrência aberta.</p>}</Panel></div>
  </>;
}

export function StandsPage() {
  const utils = trpc.useUtils();
  const properties = trpc.forest.property.list.useQuery();
  const stands = trpc.forest.stand.list.useQuery();
  const [propertyOpen, setPropertyOpen] = useState(false);
  const [standOpen, setStandOpen] = useState(false);
  const createProperty = trpc.forest.property.create.useMutation({ onSuccess: () => { toast.success("Propriedade cadastrada."); utils.forest.property.list.invalidate(); setPropertyOpen(false); }, onError: error => toast.error(error.message) });
  const createStand = trpc.forest.stand.create.useMutation({ onSuccess: () => { toast.success("Talhão cadastrado."); utils.forest.stand.list.invalidate(); utils.forest.dashboard.invalidate(); setStandOpen(false); }, onError: error => toast.error(error.message) });

  const handleProperty = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); createProperty.mutate({ name: String(form.get("name")), registry: String(form.get("registry")) || null, carNumber: String(form.get("carNumber")) || null, municipality: String(form.get("municipality")), state: String(form.get("state")), address: String(form.get("address")) || null, notes: String(form.get("notes")) || null }); };
  const handleStand = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); createStand.mutate({ propertyId: Number(form.get("propertyId")), code: String(form.get("code")), name: String(form.get("name")) || null, species: String(form.get("species")) as "pinus" | "eucalipto", areaHa: Number(form.get("areaHa")), cycleStatus: String(form.get("cycleStatus")) as "aguardando" | "primeiro_desbaste" | "segundo_desbaste" | "corte_raso", operationalStatus: String(form.get("operationalStatus")) as "ativo" | "em_colheita" | "bloqueado" | "concluido", polygonUrl: String(form.get("polygonUrl")) || null, polygonGeoJson: String(form.get("polygonGeoJson")) || null, notes: String(form.get("notes")) || null }); };
  const totalArea = useMemo(() => stands.data?.reduce((sum, item) => sum + Number(item.stand.areaHa), 0) || 0, [stands.data]);
  return <>
    <PageHeading eyebrow="Cadastro territorial" title="Talhões e áreas de produção." description="Organize espécies, ciclo silvicultural, área em hectares e o vínculo do polígono para cada talhão." action={<div className="flex flex-wrap gap-2"><Button variant="outline" onClick={() => setPropertyOpen(true)} className="border-[#bcd2c0] bg-white text-[#29573c]"><Plus className="mr-2 h-4 w-4" />Propriedade</Button><Button onClick={() => setStandOpen(true)} disabled={!properties.data?.length} className="bg-[#1f5d42] hover:bg-[#174b35] text-white"><Plus className="mr-2 h-4 w-4" />Novo talhão</Button></div>} />
    <div className="mb-5 grid gap-4 sm:grid-cols-3"><MetricCard label="Propriedades" value={String(properties.data?.length || 0)} note="Cadastradas" icon={Landmark} /><MetricCard label="Talhões" value={String(stands.data?.length || 0)} note="Registrados" icon={Trees} /><MetricCard label="Área total" value={`${number(totalArea, 2)} ha`} note="Soma dos talhões" icon={MapPin} /></div>
    <div className="mb-5 grid gap-3 sm:grid-cols-2"><Panel className="border-[#bed4d7] bg-[#f2fbfc] p-4"><p className="text-[11px] font-bold uppercase tracking-[0.14em] text-[#367181]">Pinus</p><p className="mt-1 text-sm text-[#43636a]">Talhões de Pinus aparecem com sinalização azul-petróleo em listas, filtros e relatórios.</p></Panel><Panel className="border-[#cddcc0] bg-[#f7fbef] p-4"><p className="text-[11px] font-bold uppercase tracking-[0.14em] text-[#638342]">Eucalipto</p><p className="mt-1 text-sm text-[#5f7252]">Talhões de Eucalipto aparecem com sinalização verde-oliva em listas, filtros e relatórios.</p></Panel></div>
    {!!stands.data?.length && <div className="mb-5 grid gap-3 lg:grid-cols-2"><Panel className="overflow-hidden border-[#bed4d7]"><div className="flex items-center justify-between bg-[#effafb] px-4 py-3"><div><p className="text-[11px] font-bold uppercase tracking-[0.14em] text-[#2f7482]">Pinus</p><p className="mt-1 text-xs text-[#55767b]">Talhões identificados em azul-petróleo.</p></div><span className="rounded-lg bg-[#d8f0f3] px-2.5 py-1 text-xs font-bold text-[#2f7482]">{stands.data.filter(item => item.stand.species === "pinus").length}</span></div><div className="flex flex-wrap gap-2 p-4">{stands.data.filter(item => item.stand.species === "pinus").length ? stands.data.filter(item => item.stand.species === "pinus").map(item => <span key={item.stand.id} className="rounded-lg border border-[#b8d6da] bg-white px-2.5 py-1.5 text-xs font-semibold text-[#2e7480]">{item.stand.code} · {number(item.stand.areaHa, 2)} ha</span>) : <span className="text-sm text-[#7b9394]">Nenhum talhão de Pinus cadastrado.</span>}</div></Panel><Panel className="overflow-hidden border-[#cddcc0]"><div className="flex items-center justify-between bg-[#f5faed] px-4 py-3"><div><p className="text-[11px] font-bold uppercase tracking-[0.14em] text-[#638342]">Eucalipto</p><p className="mt-1 text-xs text-[#66775c]">Talhões identificados em verde-oliva.</p></div><span className="rounded-lg bg-[#e7f0d8] px-2.5 py-1 text-xs font-bold text-[#638342]">{stands.data.filter(item => item.stand.species === "eucalipto").length}</span></div><div className="flex flex-wrap gap-2 p-4">{stands.data.filter(item => item.stand.species === "eucalipto").length ? stands.data.filter(item => item.stand.species === "eucalipto").map(item => <span key={item.stand.id} className="rounded-lg border border-[#cfdfbe] bg-white px-2.5 py-1.5 text-xs font-semibold text-[#638342]">{item.stand.code} · {number(item.stand.areaHa, 2)} ha</span>) : <span className="text-sm text-[#859578]">Nenhum talhão de Eucalipto cadastrado.</span>}</div></Panel></div>}
    {stands.isLoading || properties.isLoading ? <LoadingPanel /> : !properties.data?.length ? <EmptyPanel icon={Landmark} title="Cadastre a primeira propriedade" description="A propriedade é a base para conectar talhões, contratos, tickets, caixa, documentos e vistorias." action={<Button onClick={() => setPropertyOpen(true)} className="bg-[#1f5d42] hover:bg-[#174b35] text-white"><Plus className="mr-2 h-4 w-4" />Cadastrar propriedade</Button>} /> : <div className="grid gap-5 xl:grid-cols-[0.88fr_1.12fr]"><Panel className="overflow-hidden"><div className="border-b border-[#e5ece3] px-5 py-4"><h2 className="font-semibold text-[#173f2e]">Mapa da operação</h2><p className="mt-1 text-xs text-[#78867d]">Centro de referência: Porto União/SC e União da Vitória/PR.</p></div><MapView className="h-[360px]" initialCenter={{ lat: -26.2385, lng: -51.0788 }} initialZoom={11} /></Panel><Panel className="overflow-hidden"><div className="flex items-center justify-between border-b border-[#e5ece3] px-5 py-4"><div><h2 className="font-semibold text-[#173f2e]">Lista de talhões</h2><p className="mt-1 text-xs text-[#78867d]">Os dados de coordenadas ficam vinculados a cada cadastro.</p></div><span className="text-xs font-semibold text-[#63836e]">{stands.data?.length || 0} registros</span></div>{stands.data?.length ? <div className="divide-y divide-[#edf1eb]">{stands.data.map(item => <div key={item.stand.id} className="flex flex-col gap-3 p-5 sm:flex-row sm:items-center sm:justify-between"><div><div className="flex flex-wrap items-center gap-2"><p className="font-semibold text-[#234532]">{item.stand.code}</p><StatusPill label={labels.standStatus[item.stand.operationalStatus]} value={item.stand.operationalStatus} /></div><p className="mt-1 text-sm text-[#728078]">{item.stand.name || "Sem nome complementar"} · {item.propertyName} · {item.municipality}/{item.state}</p><div className="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-xs text-[#587060]"><span>{labels.species[item.stand.species]}</span><span>{number(item.stand.areaHa, 2)} ha</span><span>{labels.cycle[item.stand.cycleStatus]}</span></div></div><div className="flex items-center gap-2">{item.stand.polygonUrl && <a href={item.stand.polygonUrl} target="_blank" rel="noreferrer" className="rounded-lg border border-[#d1dfd1] p-2 text-[#2f704d] hover:bg-[#f1f7f0]" title="Abrir polígono"><MapPin className="h-4 w-4" /></a>}<ChevronRight className="h-5 w-5 text-[#b3c2b5]" /></div></div>)}</div> : <div className="p-10 text-center"><Trees className="mx-auto h-7 w-7 text-[#93a996]" /><h3 className="mt-3 font-semibold text-[#274a38]">Nenhum talhão registrado</h3><p className="mt-2 text-sm text-[#758379]">Cadastre o código, espécie, área e polígono para iniciar o controle.</p><Button onClick={() => setStandOpen(true)} className="mt-5 bg-[#1f5d42] hover:bg-[#174b35] text-white"><Plus className="mr-2 h-4 w-4" />Novo talhão</Button></div>}</Panel></div>}
    <Modal open={propertyOpen} onClose={() => setPropertyOpen(false)} title="Nova propriedade"><form onSubmit={handleProperty} className="grid gap-4 sm:grid-cols-2"><Field label="Nome da propriedade"><input name="name" required className={inputClass} placeholder="Ex.: Fazenda Araucária" /></Field><Field label="Município"><input name="municipality" required className={inputClass} placeholder="Porto União" /></Field><Field label="UF"><select name="state" defaultValue="SC" className={selectClass}><option value="SC">SC</option><option value="PR">PR</option></select></Field><Field label="Matrícula"><input name="registry" className={inputClass} placeholder="Número da matrícula" /></Field><Field label="CAR"><input name="carNumber" className={inputClass} placeholder="Número do CAR" /></Field><Field label="Endereço / acesso"><input name="address" className={inputClass} placeholder="Rodovia, estrada, km" /></Field><div className="sm:col-span-2"><Field label="Observações"><textarea name="notes" className={textareaClass} placeholder="Informações operacionais, restrições e referências." /></Field></div><div className="sm:col-span-2"><FormActions loading={createProperty.isPending} onCancel={() => setPropertyOpen(false)} /></div></form></Modal>
    <Modal open={standOpen} onClose={() => setStandOpen(false)} title="Novo talhão"><form onSubmit={handleStand} className="grid gap-4 sm:grid-cols-2"><Field label="Propriedade"><select name="propertyId" required className={selectClass} defaultValue=""><option value="" disabled>Selecione a propriedade</option>{properties.data?.map(property => <option key={property.id} value={property.id}>{property.name} · {property.municipality}/{property.state}</option>)}</select></Field><Field label="Código do talhão"><input name="code" required className={inputClass} placeholder="Ex.: T-01" /></Field><Field label="Nome complementar"><input name="name" className={inputClass} placeholder="Ex.: Pinus norte" /></Field><Field label="Espécie"><select name="species" className={selectClass}><option value="pinus">Pinus</option><option value="eucalipto">Eucalipto</option></select></Field><Field label="Área (ha)"><input name="areaHa" required type="number" min="0.01" step="0.01" className={inputClass} placeholder="0,00" /></Field><Field label="Ciclo silvicultural"><select name="cycleStatus" className={selectClass}><option value="aguardando">Aguardando</option><option value="primeiro_desbaste">1º desbaste</option><option value="segundo_desbaste">2º desbaste</option><option value="corte_raso">Corte raso</option></select></Field><Field label="Status operacional"><select name="operationalStatus" className={selectClass}><option value="ativo">Ativo</option><option value="em_colheita">Em colheita</option><option value="bloqueado">Bloqueado</option><option value="concluido">Concluído</option></select></Field><Field label="Link do polígono"><input name="polygonUrl" type="url" className={inputClass} placeholder="Google Maps / mapa compartilhado" /></Field><div className="sm:col-span-2"><Field label="GeoJSON / coordenadas" hint="Cole o GeoJSON ou um registro estruturado das coordenadas do polígono."><textarea name="polygonGeoJson" className={textareaClass} placeholder="{ ... }" /></Field></div><div className="sm:col-span-2"><Field label="Observações"><textarea name="notes" className={textareaClass} placeholder="APP, Reserva Legal, limites operacionais, acesso e outras restrições." /></Field></div><div className="sm:col-span-2"><FormActions loading={createStand.isPending} onCancel={() => setStandOpen(false)} /></div></form></Modal>
  </>;
}

export function TicketsPage() {
  const utils = trpc.useUtils();
  const tickets = trpc.forest.ticket.list.useQuery();
  const contracts = trpc.forest.contract.list.useQuery();
  const stands = trpc.forest.stand.list.useQuery();
  const [open, setOpen] = useState(false); const [file, setFile] = useState<File>();
  const create = trpc.forest.ticket.create.useMutation({ onSuccess: () => { toast.success("Ticket lançado para conferência."); utils.forest.ticket.list.invalidate(); utils.forest.dashboard.invalidate(); setOpen(false); setFile(undefined); }, onError: error => toast.error(error.message) });
  const updateStatus = trpc.forest.ticket.updateStatus.useMutation({ onSuccess: () => { toast.success("Situação do ticket atualizada."); utils.forest.ticket.list.invalidate(); utils.forest.dashboard.invalidate(); }, onError: error => toast.error(error.message) });
  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); try { const form = new FormData(event.currentTarget); create.mutate({ contractId: Number(form.get("contractId")), standId: Number(form.get("standId")), ticketNumber: String(form.get("ticketNumber")), issuedAt: String(form.get("issuedAt")), vehiclePlate: String(form.get("vehiclePlate")), destination: String(form.get("destination")), netWeightTons: Number(form.get("netWeightTons")), status: "pendente", notes: String(form.get("notes")) || null, file: await readUpload(file) }); } catch (error) { toast.error(error instanceof Error ? error.message : "Não foi possível ler o anexo."); } };
  const ready = Boolean(contracts.data?.length && stands.data?.length);
  return <>
    <PageHeading eyebrow="Operação de campo" title="Tickets de balança." description="Registre cada carga com talhão, contrato, placa, destino, peso e foto do comprovante para manter a rastreabilidade." action={<Button onClick={() => setOpen(true)} disabled={!ready} className="bg-[#1f5d42] hover:bg-[#174b35] text-white"><Plus className="mr-2 h-4 w-4" />Lançar ticket</Button>} />
    {!ready && !tickets.isLoading ? <EmptyPanel icon={Scale} title="Prepare a base do lançamento" description="Antes de lançar um ticket, cadastre ao menos um talhão e um contrato ativo ou em rascunho." /> : tickets.isLoading ? <LoadingPanel /> : <Panel className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left"><thead className="bg-[#f5f8f3] text-[11px] uppercase tracking-[0.1em] text-[#688071]"><tr><th className="px-5 py-3 font-semibold">Ticket</th><th className="px-5 py-3 font-semibold">Talhão e contrato</th><th className="px-5 py-3 font-semibold">Carga</th><th className="px-5 py-3 font-semibold">Destino</th><th className="px-5 py-3 font-semibold">Status</th><th className="px-5 py-3 font-semibold text-right">Ação</th></tr></thead><tbody className="divide-y divide-[#edf1eb]">{tickets.data?.length ? tickets.data.map(item => <tr key={item.ticket.id} className="text-sm text-[#3f5949]"><td className="px-5 py-4"><p className="font-semibold text-[#254934]">{item.ticket.ticketNumber}</p><p className="mt-1 text-xs text-[#7c8d82]">{dateTime(item.ticket.issuedAt)}</p></td><td className="px-5 py-4"><p>{item.standCode}</p><p className="mt-1 text-xs text-[#7c8d82]">{item.contractCode}</p></td><td className="px-5 py-4"><p className="font-semibold">{number(item.ticket.netWeightTons, 3)} t</p><p className="mt-1 text-xs text-[#7c8d82]">{item.ticket.vehiclePlate}</p></td><td className="px-5 py-4">{item.ticket.destination}</td><td className="px-5 py-4"><StatusPill label={labels.ticketStatus[item.ticket.status]} value={item.ticket.status} /></td><td className="px-5 py-4 text-right">{item.ticket.fileUrl && <a href={item.ticket.fileUrl} target="_blank" rel="noreferrer" className="mr-2 inline-flex rounded-lg border border-[#d5e1d4] p-2 text-[#2f704d] hover:bg-[#f0f7f0]" title="Ver comprovante"><FileText className="h-4 w-4" /></a>}{item.ticket.status === "pendente" && <Button size="sm" onClick={() => updateStatus.mutate({ id: item.ticket.id, status: "conferido" })} disabled={updateStatus.isPending} className="bg-[#e6f2e9] text-[#23623f] hover:bg-[#d8ebdc]"><Check className="mr-1 h-3.5 w-3.5" />Conferir</Button>}</td></tr>) : <tr><td colSpan={6} className="px-5 py-12 text-center text-sm text-[#839087]">Nenhum ticket registrado. Lance a primeira carga quando a operação iniciar.</td></tr>}</tbody></table></div></Panel>}
    <Modal open={open} onClose={() => setOpen(false)} title="Lançar ticket de balança"><form onSubmit={handleSubmit} className="grid gap-4 sm:grid-cols-2"><Field label="Talhão"><select name="standId" required className={selectClass} defaultValue=""><option value="" disabled>Selecione o talhão</option>{stands.data?.map(item => <option key={item.stand.id} value={item.stand.id}>{item.stand.code} · {item.propertyName}</option>)}</select></Field><Field label="Contrato"><select name="contractId" required className={selectClass} defaultValue=""><option value="" disabled>Selecione o contrato</option>{contracts.data?.map(item => <option key={item.contract.id} value={item.contract.id}>{item.contract.code} · {item.contract.buyerName}</option>)}</select></Field><Field label="Nº do ticket"><input name="ticketNumber" required className={inputClass} placeholder="Número impresso na balança" /></Field><Field label="Data e hora"><input name="issuedAt" required type="datetime-local" defaultValue={inputDateTime()} className={inputClass} /></Field><Field label="Placa do veículo"><input name="vehiclePlate" required className={inputClass} placeholder="ABC1D23" /></Field><Field label="Destino"><input name="destination" required className={inputClass} placeholder="Fábrica ou serraria" /></Field><Field label="Peso líquido (t)"><input name="netWeightTons" required type="number" min="0.001" step="0.001" className={inputClass} placeholder="0,000" /></Field><Field label="Foto / comprovante" hint={file ? file.name : "Imagem ou PDF de até 6 MB"}><FilePicker onChange={setFile} /></Field><div className="sm:col-span-2"><Field label="Observações"><textarea name="notes" className={textareaClass} placeholder="Informações adicionais da carga ou da balança." /></Field></div><div className="sm:col-span-2"><FormActions loading={create.isPending} onCancel={() => setOpen(false)} /></div></form></Modal>
  </>;
}

export function OperationsPage() {
  const utils = trpc.useUtils();
  const entries = trpc.forest.ledger.list.useQuery(); const properties = trpc.forest.property.list.useQuery(); const stands = trpc.forest.stand.list.useQuery(); const contracts = trpc.forest.contract.list.useQuery();
  const [open, setOpen] = useState(false); const [file, setFile] = useState<File>();
  const create = trpc.forest.ledger.create.useMutation({ onSuccess: () => { toast.success("Lançamento incluído no caixa."); utils.forest.ledger.list.invalidate(); utils.forest.dashboard.invalidate(); setOpen(false); setFile(undefined); }, onError: error => toast.error(error.message) });
  const updateStatus = trpc.forest.ledger.updateStatus.useMutation({ onSuccess: () => { toast.success("Situação financeira atualizada."); utils.forest.ledger.list.invalidate(); utils.forest.dashboard.invalidate(); }, onError: error => toast.error(error.message) });
  const totals = useMemo(() => ({ receitas: entries.data?.filter(item => item.entry.flow === "receita" && item.entry.status === "aprovado").reduce((sum, item) => sum + Number(item.entry.amount), 0) || 0, despesas: entries.data?.filter(item => item.entry.flow === "despesa" && item.entry.status === "aprovado").reduce((sum, item) => sum + Number(item.entry.amount), 0) || 0 }), [entries.data]);
  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); try { const form = new FormData(event.currentTarget); create.mutate({ propertyId: Number(form.get("propertyId")), standId: form.get("standId") ? Number(form.get("standId")) : null, contractId: form.get("contractId") ? Number(form.get("contractId")) : null, occurredAt: String(form.get("occurredAt")), flow: String(form.get("flow")) as "receita" | "despesa", category: String(form.get("category")) as "madeira_tonelada" | "area_fixa" | "manutencao" | "diarias" | "outros", description: String(form.get("description")), tons: form.get("tons") ? Number(form.get("tons")) : null, amount: Number(form.get("amount")), status: "pendente", file: await readUpload(file) }); } catch (error) { toast.error(error instanceof Error ? error.message : "Não foi possível ler o anexo."); } };
  return <>
    <PageHeading eyebrow="Financeiro" title="Caixa e operações." description="Consolide receitas, despesas, tonelagem e anexos. A aprovação alimenta os indicadores do painel." action={<Button onClick={() => setOpen(true)} disabled={!properties.data?.length} className="bg-[#1f5d42] hover:bg-[#174b35] text-white"><Plus className="mr-2 h-4 w-4" />Novo lançamento</Button>} />
    <div className="mb-5 grid gap-4 sm:grid-cols-3"><MetricCard label="Receita aprovada" value={currency(totals.receitas)} note="Caixa confirmado" icon={ArrowUpRight} /><MetricCard label="Despesa aprovada" value={currency(totals.despesas)} note="Custo confirmado" icon={ArrowDownRight} accent="gold" /><MetricCard label="Saldo operacional" value={currency(totals.receitas - totals.despesas)} note="Receitas menos despesas" icon={Landmark} accent={totals.receitas - totals.despesas >= 0 ? "green" : "red"} /></div>
    {entries.isLoading ? <LoadingPanel /> : !properties.data?.length ? <EmptyPanel icon={Landmark} title="Cadastre uma propriedade primeiro" description="O caixa precisa estar associado a uma propriedade para manter a rastreabilidade da operação." /> : <Panel className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[810px] text-left"><thead className="bg-[#f5f8f3] text-[11px] uppercase tracking-[0.1em] text-[#688071]"><tr><th className="px-5 py-3">Data</th><th className="px-5 py-3">Descrição</th><th className="px-5 py-3">Vínculo</th><th className="px-5 py-3">Fluxo</th><th className="px-5 py-3 text-right">Valor</th><th className="px-5 py-3">Status</th><th className="px-5 py-3 text-right">Ação</th></tr></thead><tbody className="divide-y divide-[#edf1eb]">{entries.data?.length ? entries.data.map(item => <tr key={item.entry.id} className="text-sm text-[#3f5949]"><td className="px-5 py-4 text-xs">{date(item.entry.occurredAt)}</td><td className="px-5 py-4"><p className="font-semibold text-[#254934]">{item.entry.description}</p><p className="mt-1 text-xs text-[#7c8d82]">{labels.category[item.entry.category]} {item.entry.tons ? `· ${number(item.entry.tons, 3)} t` : ""}</p></td><td className="px-5 py-4 text-xs">{item.standCode || "Propriedade"}{item.contractCode ? ` · ${item.contractCode}` : ""}</td><td className="px-5 py-4"><StatusPill label={labels.flow[item.entry.flow]} value={item.entry.flow === "receita" ? "aprovado" : "atencao"} /></td><td className={`px-5 py-4 text-right font-semibold ${item.entry.flow === "receita" ? "text-[#267044]" : "text-[#a36931]"}`}>{currency(item.entry.amount)}</td><td className="px-5 py-4"><StatusPill label={labels.entryStatus[item.entry.status]} value={item.entry.status} /></td><td className="px-5 py-4 text-right">{item.entry.fileUrl && <a href={item.entry.fileUrl} target="_blank" rel="noreferrer" className="mr-2 inline-flex rounded-lg border border-[#d5e1d4] p-2 text-[#2f704d]"><FileText className="h-4 w-4" /></a>}{item.entry.status === "pendente" && <Button size="sm" onClick={() => updateStatus.mutate({ id: item.entry.id, status: "aprovado" })} className="bg-[#e6f2e9] text-[#23623f] hover:bg-[#d8ebdc]"><Check className="mr-1 h-3.5 w-3.5" />Aprovar</Button>}</td></tr>) : <tr><td colSpan={7} className="px-5 py-12 text-center text-sm text-[#839087]">Sem lançamentos financeiros. Inclua receitas, despesas e documentos de apoio.</td></tr>}</tbody></table></div></Panel>}
    <Modal open={open} onClose={() => setOpen(false)} title="Novo lançamento financeiro"><form onSubmit={handleSubmit} className="grid gap-4 sm:grid-cols-2"><Field label="Propriedade"><select name="propertyId" required className={selectClass} defaultValue=""><option value="" disabled>Selecione a propriedade</option>{properties.data?.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><Field label="Data e hora"><input name="occurredAt" type="datetime-local" required defaultValue={inputDateTime()} className={inputClass} /></Field><Field label="Fluxo"><select name="flow" className={selectClass}><option value="receita">Receita</option><option value="despesa">Despesa</option></select></Field><Field label="Categoria"><select name="category" className={selectClass}><option value="madeira_tonelada">Madeira / tonelada</option><option value="area_fixa">Área fixa</option><option value="manutencao">Manutenção</option><option value="diarias">Diárias</option><option value="outros">Outros</option></select></Field><Field label="Talhão (opcional)"><select name="standId" className={selectClass} defaultValue=""><option value="">Não vincular</option>{stands.data?.map(item => <option key={item.stand.id} value={item.stand.id}>{item.stand.code}</option>)}</select></Field><Field label="Contrato (opcional)"><select name="contractId" className={selectClass} defaultValue=""><option value="">Não vincular</option>{contracts.data?.map(item => <option key={item.contract.id} value={item.contract.id}>{item.contract.code}</option>)}</select></Field><Field label="Descrição"><input name="description" required className={inputClass} placeholder="Ex.: frete, manutenção, recebimento" /></Field><Field label="Valor (R$)"><input name="amount" required type="number" min="0" step="0.01" className={inputClass} placeholder="0,00" /></Field><Field label="Toneladas (se aplicável)"><input name="tons" type="number" min="0" step="0.001" className={inputClass} placeholder="0,000" /></Field><Field label="Anexo" hint={file ? file.name : "Comprovante ou ticket (até 6 MB)"}><FilePicker onChange={setFile} /></Field><div className="sm:col-span-2"><FormActions loading={create.isPending} onCancel={() => setOpen(false)} /></div></form></Modal>
  </>;
}

export function ContractsPage() {
  const utils = trpc.useUtils(); const contracts = trpc.forest.contract.list.useQuery(); const properties = trpc.forest.property.list.useQuery(); const stands = trpc.forest.stand.list.useQuery();
  const [open, setOpen] = useState(false); const [file, setFile] = useState<File>();
  const create = trpc.forest.contract.create.useMutation({ onSuccess: () => { toast.success("Contrato cadastrado."); utils.forest.contract.list.invalidate(); utils.forest.dashboard.invalidate(); setOpen(false); setFile(undefined); }, onError: error => toast.error(error.message) });
  const updateStatus = trpc.forest.contract.updateStatus.useMutation({ onSuccess: () => { toast.success("Situação contratual atualizada."); utils.forest.contract.list.invalidate(); utils.forest.dashboard.invalidate(); }, onError: error => toast.error(error.message) });
  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); try { const form = new FormData(event.currentTarget); const type = String(form.get("type")) as "por_tonelada" | "preco_fixo"; create.mutate({ propertyId: Number(form.get("propertyId")), standId: form.get("standId") ? Number(form.get("standId")) : null, code: String(form.get("code")), buyerName: String(form.get("buyerName")), buyerDocument: String(form.get("buyerDocument")) || null, type, status: "rascunho", pricePerTon: type === "por_tonelada" && form.get("pricePerTon") ? Number(form.get("pricePerTon")) : null, fixedValue: type === "preco_fixo" && form.get("fixedValue") ? Number(form.get("fixedValue")) : null, receivedValue: Number(form.get("receivedValue") || 0), startDate: form.get("startDate") ? String(form.get("startDate")) : null, deadline: form.get("deadline") ? String(form.get("deadline")) : null, guaranteeType: String(form.get("guaranteeType")) as "nenhuma" | "nota_promissoria" | "fiador" | "seguro_garantia" | "caucao", guaranteeValue: form.get("guaranteeValue") ? Number(form.get("guaranteeValue")) : null, notes: String(form.get("notes")) || null, file: await readUpload(file) }); } catch (error) { toast.error(error instanceof Error ? error.message : "Não foi possível ler o anexo."); } };
  return <>
    <PageHeading eyebrow="Gestão contratual" title="Contratos, garantias e prazos." description="Acompanhe venda por tonelada e porteira fechada, com vencimentos, garantias, anexos e situação da operação." action={<Button onClick={() => setOpen(true)} disabled={!properties.data?.length} className="bg-[#1f5d42] hover:bg-[#174b35] text-white"><Plus className="mr-2 h-4 w-4" />Novo contrato</Button>} />
    {contracts.isLoading ? <LoadingPanel /> : !properties.data?.length ? <EmptyPanel icon={ScrollText} title="Cadastre a propriedade primeiro" description="O contrato precisa indicar a propriedade e, quando aplicável, o talhão abrangido pela operação." /> : contracts.data?.length ? <div className="grid gap-4 lg:grid-cols-2">{contracts.data.map(item => <Panel key={item.contract.id} className="p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex flex-wrap items-center gap-2"><p className="font-semibold text-[#173f2e]">{item.contract.code}</p><StatusPill label={labels.contractStatus[item.contract.status]} value={item.contract.status} /></div><p className="mt-2 text-sm text-[#5f7466]">{item.contract.buyerName}</p><p className="mt-1 text-xs text-[#809086]">{item.propertyName}{item.standCode ? ` · ${item.standCode}` : ""}</p></div><div className="rounded-xl bg-[#eef5ed] px-3 py-2 text-right"><p className="text-[10px] uppercase tracking-[0.08em] text-[#799080]">Modalidade</p><p className="mt-1 text-xs font-semibold text-[#2c6544]">{labels.contractType[item.contract.type]}</p></div></div><div className="mt-5 grid grid-cols-2 gap-3 border-y border-[#edf1eb] py-4 text-sm"><div><p className="text-xs text-[#819087]">Valor contratual</p><p className="mt-1 font-semibold text-[#244935]">{item.contract.type === "por_tonelada" ? `${currency(item.contract.pricePerTon)} / t` : currency(item.contract.fixedValue)}</p></div><div><p className="text-xs text-[#819087]">Garantia</p><p className="mt-1 font-semibold text-[#244935]">{labels.guarantee[item.contract.guaranteeType]}{item.contract.guaranteeValue ? ` · ${currency(item.contract.guaranteeValue)}` : ""}</p></div><div><p className="text-xs text-[#819087]">Prazo final</p><p className="mt-1 font-semibold text-[#244935]">{date(item.contract.deadline)}</p></div><div><p className="text-xs text-[#819087]">Recebido</p><p className="mt-1 font-semibold text-[#244935]">{currency(item.contract.receivedValue)}</p></div></div><div className="mt-4 flex items-center justify-between gap-3"><div className="flex items-center gap-2">{item.contract.documentUrl && <a href={item.contract.documentUrl} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1.5 text-xs font-semibold text-[#2b6a47] hover:underline"><FileText className="h-4 w-4" />Ver arquivo</a>}</div><div>{item.contract.status === "rascunho" && <Button size="sm" onClick={() => updateStatus.mutate({ id: item.contract.id, status: "ativo" })} className="bg-[#e6f2e9] text-[#23623f] hover:bg-[#d8ebdc]"><Check className="mr-1 h-3.5 w-3.5" />Ativar</Button>}{item.contract.status === "ativo" && <Button size="sm" variant="outline" onClick={() => updateStatus.mutate({ id: item.contract.id, status: "suspenso" })} className="border-[#f0d2ca] bg-[#fffaf9] text-[#a94a3c]">Suspender</Button>}</div></div></Panel>)}</div> : <EmptyPanel icon={ScrollText} title="Nenhum contrato cadastrado" description="Registre os contratos de venda por tonelada ou por preço fixo, vinculando garantia e prazo de extração." action={<Button onClick={() => setOpen(true)} className="bg-[#1f5d42] hover:bg-[#174b35] text-white"><Plus className="mr-2 h-4 w-4" />Cadastrar contrato</Button>} />}
    <Modal open={open} onClose={() => setOpen(false)} title="Novo contrato"><form onSubmit={handleSubmit} className="grid gap-4 sm:grid-cols-2"><Field label="Propriedade"><select name="propertyId" required className={selectClass} defaultValue=""><option value="" disabled>Selecione a propriedade</option>{properties.data?.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><Field label="Talhão (opcional)"><select name="standId" className={selectClass} defaultValue=""><option value="">Lote / mais de um talhão</option>{stands.data?.map(item => <option key={item.stand.id} value={item.stand.id}>{item.stand.code}</option>)}</select></Field><Field label="Código"><input name="code" required className={inputClass} placeholder="CT-2026-001" /></Field><Field label="Comprador"><input name="buyerName" required className={inputClass} placeholder="Nome ou razão social" /></Field><Field label="CPF/CNPJ do comprador"><input name="buyerDocument" className={inputClass} placeholder="Documento" /></Field><Field label="Modalidade"><select name="type" className={selectClass}><option value="por_tonelada">Venda por tonelada</option><option value="preco_fixo">Preço fixo / porteira fechada</option></select></Field><Field label="Preço por tonelada (R$)" hint="Preencha para venda por tonelada."><input name="pricePerTon" type="number" min="0" step="0.01" className={inputClass} placeholder="0,00" /></Field><Field label="Valor fixo (R$)" hint="Preencha para porteira fechada."><input name="fixedValue" type="number" min="0" step="0.01" className={inputClass} placeholder="0,00" /></Field><Field label="Valor já recebido (R$)"><input name="receivedValue" type="number" min="0" step="0.01" defaultValue="0" className={inputClass} /></Field><Field label="Início previsto"><input name="startDate" type="datetime-local" className={inputClass} /></Field><Field label="Prazo final"><input name="deadline" type="datetime-local" className={inputClass} /></Field><Field label="Garantia"><select name="guaranteeType" className={selectClass}><option value="nenhuma">Sem garantia</option><option value="nota_promissoria">Nota promissória</option><option value="fiador">Fiador</option><option value="seguro_garantia">Seguro-garantia</option><option value="caucao">Caução</option></select></Field><Field label="Valor garantido (R$)"><input name="guaranteeValue" type="number" min="0" step="0.01" className={inputClass} placeholder="0,00" /></Field><Field label="Arquivo do contrato" hint={file ? file.name : "PDF ou imagem de até 6 MB"}><FilePicker onChange={setFile} accept="application/pdf,image/*" /></Field><div className="sm:col-span-2"><Field label="Observações e obrigações críticas"><textarea name="notes" className={textareaClass} placeholder="Polígono, tickets, multa, prazo, infraestrutura, chuva, incêndio e demais proteções." /></Field></div><div className="sm:col-span-2"><FormActions loading={create.isPending} onCancel={() => setOpen(false)} /></div></form></Modal>
  </>;
}

export function DocumentsPage() {
  const utils = trpc.useUtils(); const documents = trpc.forest.document.list.useQuery(); const properties = trpc.forest.property.list.useQuery(); const stands = trpc.forest.stand.list.useQuery(); const contracts = trpc.forest.contract.list.useQuery();
  const [open, setOpen] = useState(false); const [file, setFile] = useState<File>();
  const create = trpc.forest.document.create.useMutation({ onSuccess: () => { toast.success("Arquivo salvo com segurança."); utils.forest.document.list.invalidate(); setOpen(false); setFile(undefined); }, onError: error => toast.error(error.message) });
  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); try { const form = new FormData(event.currentTarget); create.mutate({ propertyId: Number(form.get("propertyId")), standId: form.get("standId") ? Number(form.get("standId")) : null, contractId: form.get("contractId") ? Number(form.get("contractId")) : null, title: String(form.get("title")), type: String(form.get("type")) as "contrato" | "relatorio_vistoria" | "tarefa" | "licenca" | "garantia" | "outro", file: await readUpload(file) }); } catch (error) { toast.error(error instanceof Error ? error.message : "Selecione um arquivo de até 6 MB."); } };
  return <>
    <PageHeading eyebrow="Repositório seguro" title="Arquivos e documentação." description="Centralize contratos, vistorias, licenças, garantias e relatórios, sempre vinculados à operação correta." action={<Button onClick={() => setOpen(true)} disabled={!properties.data?.length} className="bg-[#1f5d42] hover:bg-[#174b35] text-white"><FilePlus2 className="mr-2 h-4 w-4" />Enviar arquivo</Button>} />
    {documents.isLoading ? <LoadingPanel /> : !properties.data?.length ? <EmptyPanel icon={FolderOpen} title="Cadastre uma propriedade para organizar os arquivos" description="A documentação será agrupada por propriedade, talhão e contrato quando esses vínculos forem informados." /> : documents.data?.length ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{documents.data.map(item => <Panel key={item.document.id} className="group p-5"><div className="flex items-start justify-between"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#eef5ed] text-[#2e704c]"><FileText className="h-5 w-5" /></div><StatusPill label={labels.documentType[item.document.type]} value="conferido" /></div><h2 className="mt-5 truncate font-semibold text-[#173f2e]">{item.document.title}</h2><p className="mt-2 text-xs leading-5 text-[#7a897f]">{item.propertyName}{item.standCode ? ` · ${item.standCode}` : ""}{item.contractCode ? ` · ${item.contractCode}` : ""}</p><div className="mt-5 flex items-center justify-between border-t border-[#edf1eb] pt-4"><p className="text-xs text-[#8a978f]">Atualizado {date(item.document.updatedAt)}</p><a href={item.document.fileUrl} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 text-xs font-semibold text-[#2c6a47] hover:underline">Abrir<ChevronRight className="h-3.5 w-3.5" /></a></div></Panel>)}</div> : <EmptyPanel icon={FolderOpen} title="Nenhum arquivo no repositório" description="Envie os modelos de contrato, licenças, laudos, garantias e relatórios de vistoria." action={<Button onClick={() => setOpen(true)} className="bg-[#1f5d42] hover:bg-[#174b35] text-white"><FilePlus2 className="mr-2 h-4 w-4" />Enviar primeiro arquivo</Button>} />}
    <Modal open={open} onClose={() => setOpen(false)} title="Enviar arquivo"><form onSubmit={handleSubmit} className="grid gap-4 sm:grid-cols-2"><Field label="Propriedade"><select name="propertyId" required className={selectClass} defaultValue=""><option value="" disabled>Selecione a propriedade</option>{properties.data?.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><Field label="Tipo"><select name="type" className={selectClass}><option value="contrato">Contrato</option><option value="relatorio_vistoria">Relatório de vistoria</option><option value="tarefa">Tarefa</option><option value="licenca">Licença</option><option value="garantia">Garantia</option><option value="outro">Outro</option></select></Field><Field label="Título"><input name="title" required className={inputClass} placeholder="Ex.: Contrato CT-2026-001 assinado" /></Field><Field label="Talhão (opcional)"><select name="standId" className={selectClass} defaultValue=""><option value="">Não vincular</option>{stands.data?.map(item => <option key={item.stand.id} value={item.stand.id}>{item.stand.code}</option>)}</select></Field><Field label="Contrato (opcional)"><select name="contractId" className={selectClass} defaultValue=""><option value="">Não vincular</option>{contracts.data?.map(item => <option key={item.contract.id} value={item.contract.id}>{item.contract.code}</option>)}</select></Field><Field label="Arquivo" hint={file ? file.name : "PDF ou imagem de até 6 MB"}><FilePicker onChange={setFile} accept="application/pdf,image/*" /></Field><div className="sm:col-span-2"><FormActions loading={create.isPending} onCancel={() => setOpen(false)} /></div></form></Modal>
  </>;
}

export function InspectionsPage() {
  const utils = trpc.useUtils(); const inspections = trpc.forest.inspection.list.useQuery(); const properties = trpc.forest.property.list.useQuery(); const stands = trpc.forest.stand.list.useQuery(); const [open, setOpen] = useState(false); const [file, setFile] = useState<File>();
  const create = trpc.forest.inspection.create.useMutation({ onSuccess: () => { toast.success("Vistoria registrada."); utils.forest.inspection.list.invalidate(); setOpen(false); setFile(undefined); }, onError: error => toast.error(error.message) });
  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); try { const form = new FormData(event.currentTarget); create.mutate({ propertyId: Number(form.get("propertyId")), standId: Number(form.get("standId")), inspectedAt: String(form.get("inspectedAt")), inspectorName: String(form.get("inspectorName")), type: String(form.get("type")) as "infraestrutura" | "seguranca" | "ambiental" | "colheita" | "entrega_final", result: String(form.get("result")) as "conforme" | "atencao" | "nao_conforme", notes: String(form.get("notes")) || null, file: await readUpload(file) }); } catch (error) { toast.error(error instanceof Error ? error.message : "Não foi possível ler o anexo."); } };
  const ready = Boolean(properties.data?.length && stands.data?.length);
  return <>
    <PageHeading eyebrow="Controle de campo" title="Vistorias e entrega de área." description="Documente infraestrutura, segurança, meio ambiente, colheita e entrega final com situação, observações e evidências." action={<Button onClick={() => setOpen(true)} disabled={!ready} className="bg-[#1f5d42] hover:bg-[#174b35] text-white"><ClipboardCheck className="mr-2 h-4 w-4" />Nova vistoria</Button>} />
    {inspections.isLoading ? <LoadingPanel /> : !ready ? <EmptyPanel icon={ClipboardCheck} title="Cadastre propriedade e talhão" description="A vistoria precisa ser atribuída a uma área específica para preservar o histórico técnico e operacional." /> : inspections.data?.length ? <div className="grid gap-4 lg:grid-cols-2">{inspections.data.map(item => <Panel key={item.inspection.id} className="p-5"><div className="flex items-start justify-between gap-4"><div><p className="font-semibold text-[#173f2e]">{labels.inspectionType[item.inspection.type]}</p><p className="mt-1 text-sm text-[#708076]">{item.standCode} · {item.propertyName}</p></div><StatusPill label={labels.inspectionResult[item.inspection.result]} value={item.inspection.result} /></div><p className="mt-4 text-sm leading-6 text-[#53675b]">{item.inspection.notes || "Sem observações adicionais."}</p><div className="mt-5 flex items-center justify-between border-t border-[#edf1eb] pt-4 text-xs text-[#809087]"><span>{item.inspection.inspectorName} · {dateTime(item.inspection.inspectedAt)}</span>{item.inspection.photoUrl && <a href={item.inspection.photoUrl} target="_blank" rel="noreferrer" className="font-semibold text-[#2c6a47] hover:underline">Ver foto</a>}</div></Panel>)}</div> : <EmptyPanel icon={ClipboardCheck} title="Nenhuma vistoria realizada" description="Inicie pelo estado das estradas, cercas, porteiras, APP, resíduos ou pela entrega final de uma área." action={<Button onClick={() => setOpen(true)} className="bg-[#1f5d42] hover:bg-[#174b35] text-white"><ClipboardCheck className="mr-2 h-4 w-4" />Registrar vistoria</Button>} />}
    <Modal open={open} onClose={() => setOpen(false)} title="Nova vistoria"><form onSubmit={handleSubmit} className="grid gap-4 sm:grid-cols-2"><Field label="Propriedade"><select name="propertyId" required className={selectClass} defaultValue=""><option value="" disabled>Selecione a propriedade</option>{properties.data?.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><Field label="Talhão"><select name="standId" required className={selectClass} defaultValue=""><option value="" disabled>Selecione o talhão</option>{stands.data?.map(item => <option key={item.stand.id} value={item.stand.id}>{item.stand.code}</option>)}</select></Field><Field label="Data e hora"><input name="inspectedAt" type="datetime-local" required defaultValue={inputDateTime()} className={inputClass} /></Field><Field label="Responsável pela vistoria"><input name="inspectorName" required className={inputClass} placeholder="Nome completo" /></Field><Field label="Tipo"><select name="type" className={selectClass}><option value="infraestrutura">Infraestrutura</option><option value="seguranca">Segurança</option><option value="ambiental">Ambiental</option><option value="colheita">Colheita</option><option value="entrega_final">Entrega final</option></select></Field><Field label="Resultado"><select name="result" className={selectClass}><option value="conforme">Conforme</option><option value="atencao">Atenção</option><option value="nao_conforme">Não conforme</option></select></Field><Field label="Foto / evidência" hint={file ? file.name : "Imagem ou PDF de até 6 MB"}><FilePicker onChange={setFile} /></Field><div className="sm:col-span-2"><Field label="Observações"><textarea name="notes" className={textareaClass} placeholder="Condições de vias, cercas, porteiras, solo, APP, resíduos, segurança ou pendências." /></Field></div><div className="sm:col-span-2"><FormActions loading={create.isPending} onCancel={() => setOpen(false)} /></div></form></Modal>
  </>;
}

export function IncidentsPage() {
  const utils = trpc.useUtils(); const incidents = trpc.forest.incident.list.useQuery(); const properties = trpc.forest.property.list.useQuery(); const stands = trpc.forest.stand.list.useQuery(); const contracts = trpc.forest.contract.list.useQuery(); const [open, setOpen] = useState(false); const [file, setFile] = useState<File>();
  const create = trpc.forest.incident.create.useMutation({ onSuccess: () => { toast.success("Ocorrência registrada."); utils.forest.incident.list.invalidate(); utils.forest.dashboard.invalidate(); setOpen(false); setFile(undefined); }, onError: error => toast.error(error.message) });
  const updateStatus = trpc.forest.incident.updateStatus.useMutation({ onSuccess: () => { toast.success("Ocorrência atualizada."); utils.forest.incident.list.invalidate(); utils.forest.dashboard.invalidate(); }, onError: error => toast.error(error.message) });
  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); try { const form = new FormData(event.currentTarget); create.mutate({ propertyId: Number(form.get("propertyId")), standId: form.get("standId") ? Number(form.get("standId")) : null, contractId: form.get("contractId") ? Number(form.get("contractId")) : null, occurredAt: String(form.get("occurredAt")), category: String(form.get("category")) as "acesso" | "ticket" | "infraestrutura" | "chuva" | "incendio" | "ambiental" | "seguranca" | "outro", severity: String(form.get("severity")) as "baixa" | "media" | "alta" | "critica", status: "aberta", title: String(form.get("title")), description: String(form.get("description")), file: await readUpload(file) }); } catch (error) { toast.error(error instanceof Error ? error.message : "Não foi possível ler o anexo."); } };
  return <>
    <PageHeading eyebrow="Proteção patrimonial e operacional" title="Ocorrências e riscos." description="Registre desvios, tickets pendentes, chuvas, danos em infraestrutura, risco de incêndio, questões ambientais e segurança." action={<Button onClick={() => setOpen(true)} disabled={!properties.data?.length} className="bg-[#a4503f] hover:bg-[#8c3f31] text-white"><AlertTriangle className="mr-2 h-4 w-4" />Registrar ocorrência</Button>} />
    {incidents.isLoading ? <LoadingPanel /> : !properties.data?.length ? <EmptyPanel icon={AlertTriangle} title="Cadastre uma propriedade primeiro" description="As ocorrências são vinculadas à propriedade e, quando aplicável, ao talhão e ao contrato envolvidos." /> : incidents.data?.length ? <div className="grid gap-4 lg:grid-cols-2">{incidents.data.map(item => <Panel key={item.incident.id} className="p-5"><div className="flex items-start justify-between gap-3"><div><div className="flex flex-wrap items-center gap-2"><p className="font-semibold text-[#173f2e]">{item.incident.title}</p><StatusPill label={labels.severity[item.incident.severity]} value={item.incident.severity} /></div><p className="mt-2 text-xs text-[#77877d]">{labels.incidentCategory[item.incident.category]} · {item.standCode || item.propertyName} · {dateTime(item.incident.occurredAt)}</p></div><StatusPill label={labels.incidentStatus[item.incident.status]} value={item.incident.status} /></div><p className="mt-4 text-sm leading-6 text-[#53675b]">{item.incident.description}</p><div className="mt-5 flex items-center justify-between gap-3 border-t border-[#edf1eb] pt-4">{item.incident.photoUrl ? <a href={item.incident.photoUrl} target="_blank" rel="noreferrer" className="text-xs font-semibold text-[#2c6a47] hover:underline">Ver evidência</a> : <span className="text-xs text-[#8a978f]">Sem anexo</span>}{item.incident.status !== "resolvida" && <Button size="sm" onClick={() => updateStatus.mutate({ id: item.incident.id, status: "resolvida" })} className="bg-[#e6f2e9] text-[#23623f] hover:bg-[#d8ebdc]"><Check className="mr-1 h-3.5 w-3.5" />Resolver</Button>}</div></Panel>)}</div> : <EmptyPanel icon={AlertTriangle} title="Nenhuma ocorrência registrada" description="Use este módulo para manter um histórico auditável de riscos, medidas corretivas e evidências." action={<Button onClick={() => setOpen(true)} className="bg-[#a4503f] hover:bg-[#8c3f31] text-white"><AlertTriangle className="mr-2 h-4 w-4" />Registrar ocorrência</Button>} />}
    <Modal open={open} onClose={() => setOpen(false)} title="Registrar ocorrência"><form onSubmit={handleSubmit} className="grid gap-4 sm:grid-cols-2"><Field label="Propriedade"><select name="propertyId" required className={selectClass} defaultValue=""><option value="" disabled>Selecione a propriedade</option>{properties.data?.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><Field label="Talhão (opcional)"><select name="standId" className={selectClass} defaultValue=""><option value="">Não vincular</option>{stands.data?.map(item => <option key={item.stand.id} value={item.stand.id}>{item.stand.code}</option>)}</select></Field><Field label="Contrato (opcional)"><select name="contractId" className={selectClass} defaultValue=""><option value="">Não vincular</option>{contracts.data?.map(item => <option key={item.contract.id} value={item.contract.id}>{item.contract.code}</option>)}</select></Field><Field label="Data e hora"><input name="occurredAt" type="datetime-local" required defaultValue={inputDateTime()} className={inputClass} /></Field><Field label="Categoria"><select name="category" className={selectClass}><option value="acesso">Acesso</option><option value="ticket">Ticket</option><option value="infraestrutura">Infraestrutura</option><option value="chuva">Chuva</option><option value="incendio">Incêndio</option><option value="ambiental">Ambiental</option><option value="seguranca">Segurança</option><option value="outro">Outro</option></select></Field><Field label="Gravidade"><select name="severity" className={selectClass}><option value="baixa">Baixa</option><option value="media">Média</option><option value="alta">Alta</option><option value="critica">Crítica</option></select></Field><Field label="Título"><input name="title" required className={inputClass} placeholder="Ex.: Tráfego após chuva forte" /></Field><Field label="Foto / evidência" hint={file ? file.name : "Imagem ou PDF de até 6 MB"}><FilePicker onChange={setFile} /></Field><div className="sm:col-span-2"><Field label="Descrição"><textarea name="description" required className={textareaClass} placeholder="Descreva o fato, local, envolvidos, medidas tomadas e próximos passos." /></Field></div><div className="sm:col-span-2"><FormActions loading={create.isPending} onCancel={() => setOpen(false)} /></div></form></Modal>
  </>;
}
